import Combine

// ANTI-PATTERN: This creates a retain cycle and undefined behavior
class BrokenViewModel: ObservableObject {
    @Published var items: [Item] = []
    var cancellables = Set<AnyCancellable>()

    // DEATH SPIRAL: Self captured strongly in sink
    func fetchData() {
        APIClient.shared.fetch()
            .sink(receiveCompletion: { _ in },
                  receiveValue: { self.items = $0 }) // RETAIN CYCLE
            .store(in: &cancellables)
    }
}

// CORRECT: Proper lifecycle management with weak self
class RobustViewModel: ObservableObject {
    @Published var items: [Item] = []
    @Published var isLoading = false
    @Published var error: Error?

    private var fetchTask: Task<Void, Never>?
    private let repository: ItemRepository
    private var stateMachine: StateMachine?

    init(repository: ItemRepository = .shared) {
        self.repository = repository
        setupStateMachine()
    }

    private func setupStateMachine() {
        // State machine breaks retain cycles by decoupling state transitions
        stateMachine = StateMachine { [weak self] event in
            guard let self = self else { return }
            switch event {
            case .loading:
                self.isLoading = true
                self.error = nil
            case .success(let items):
                self.isLoading = false
                self.items = items
            case .failure(let error):
                self.isLoading = false
                self.error = error
            }
        }
    }

    func fetch() {
        fetchTask?.cancel()
        fetchTask = Task { [weak stateMachine] in
            stateMachine?.send(.loading)
            do {
                let items = try await repository.fetch()
                await MainActor.run {
                    stateMachine?.send(.success(items))
                }
            } catch {
                await MainActor.run {
                    stateMachine?.send(.failure(error))
                }
            }
        }
    }

    deinit {
        fetchTask?.cancel()
        print("Clean deinit - no retain cycle")
    }
}

struct ProperOwnershipView: View {
    // StateObject owns the instance - survives View identity changes
    @StateObject private var viewModel: RobustViewModel

    init(repository: ItemRepository = .shared) {
        // Must initialize here, not in body
        _viewModel = StateObject(wrappedValue: RobustViewModel(repository: repository))
    }

    var body: some View {
        List(viewModel.items) { item in
            ItemRow(item: item)
        }
        .task {
            await viewModel.fetch()
        }
    }
}",
