function encode(text){
  const v = new Float32Array(64);

  for (let i = 0; i < 64; i++) {
    let h = 2166136261;

    for (let j = 0; j < text.length; j++) {
      h ^= text.charCodeAt(j);
      h *= 16777619;
      h += i * 97;
    }

    v[i] = (Math.sin(h) * 0.5 + 0.5);
  }

  return v;
}
