function updateField(A, X, Y, lr, decay){
  for (let i = 0; i < 64; i++) {
    for (let j = 0; j < 64; j++) {

      const idx = i * 64 + j;

      A[idx] *= decay;
      A[idx] += lr * X[i] * Y[j];
    }
  }
