🧠 6. PROJECTION OPERATOR
function project(A, X){
  const out = new Float32Array(64);

  for (let i = 0; i < 64; i++) {
    let sum = 0;

    for (let j = 0; j < 64; j++) {
      sum += A[i * 64 + j] * X[j];
    }

    out[i] = sum;
  }

  return out;
}
🧠 7. CONTRADICTION FUNCTION
function cosine(a, b){
  let dot = 0, na = 0, nb = 0;

  for (let i = 0; i < 64; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }

  return dot / (Math.sqrt(na * nb) + 1e-8);
}

function contradiction(a, b){
  return 1 - cosine(a, b);
}
