3.1 Common Intermediate Representation with Lineage (src/core/cir.js)

```javascript
const crypto = require('crypto');

class CIR {
constructor(raw, type, metadata = {}) {
this.id = crypto.randomUUID();
this.timestamp = Date.now();
this.raw = raw;
this.type = type; // 'text', 'json', 'numeric', 'image', 'stream-chunk', 'log'
this.normalized = this.normalize(raw, type);
this.metadata = {
source: metadata.source || 'api',
size: JSON.stringify(raw).length,
hash: this.hash(raw),
content_type: metadata.content_type || type,
...metadata
};
}

normalize(raw, type) {
switch(type) {
case 'text':
return { text: raw, tokens_estimate: this.estimateTokens(raw) };
case 'json':
try {
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
return { json: parsed, keys: Object.keys(parsed), depth: this.jsonDepth(parsed) };
} catch(e) {
return { error: 'invalid_json', raw_string: String(raw) };
}
case 'numeric':
const arr = Array.isArray(raw) ? raw : [raw];
const flat = arr.flat(Infinity).filter(v => typeof v === 'number');
return {
values: flat,
min: Math.min(...flat),
max: Math.max(...flat),
mean: flat.reduce((a,b) => a+b, 0) / flat.length,
length: flat.length,
is_matrix: Array.isArray(arr[0])
};
case 'image':
return {
uri: typeof raw === 'string' ? raw : raw.uri,
width: metadata.width,
height: metadata.height,
format: metadata.format
};
default:
return { fallback: String(raw) };
}
}

estimateTokens(text) {
// Rough estimate: 1 token per 4 chars for English
return Math.ceil(String(text).length / 4);
}

jsonDepth(obj, depth = 0) {
if (!obj || typeof obj !== 'object') return depth;
return Math.max(...Object.values(obj).map(v => this.jsonDepth(v, depth + 1)));
}

hash(obj) {
const str = JSON.stringify(obj);
return crypto.createHash('sha256').update(str).digest('hex').substring(0, 16);
}
}

module.exports = { CIR };
```

