class BaseMiniLearner {
constructor(config) {
this.id = config.id || crypto.randomUUID();
this.parentKernelId = config.parentKernelId;
this.name = config.name || `learner_${this.id.substring(0, 8)}`;
this.model = config.model || 'llama3.2:3b';
this.initializationSeed = config.initializationSeed || Math.random();
this.specialization = config.specialization || 'general'; // general, syntax, semantics, structure, etc.
this.memory = {
history: [],
specializationScore: 0,
acceptedCount: 0
};
this.systemPrompt = this.buildSystemPrompt();
}

buildSystemPrompt() {
return `You are Mini-Learner ${this.name} (seed: ${this.initializationSeed.toFixed(4)}).
Specialization: ${this.specialization}

Your job:
1. Process the input data according to your specialization
2. Generate a hypothesis about the data
3. Output your confidence level
4. Explain your reasoning

You are part of a mini-forest. Other learners will see the same data differently.
Disagreement is valuable.

Output JSON format:
{
"hypothesis": "...",
"confidence": 0.0-1.0,
"reasoning": "...",
"specialization_match": 0.0-1.0
}`;
}

async process(cir, context = {}) {
const prompt = this.buildProcessPrompt(cir, context);

const response = await ollamaClient.chat(this.model, this.systemPrompt, prompt);
const parsed = this.parseResponse(response);

// Update memory
this.memory.history.push({
input_id: cir.id,
hypothesis: parsed.hypothesis,
confidence: parsed.confidence,
timestamp: Date.now()
});
if (this.memory.history.length > 100) this.memory.history.shift();

if (parsed.confidence > 0.7) this.memory.acceptedCount++;

return {
learner_id: this.id,
learner_name: this.name,
specialization: this.specialization,
hypothesis: parsed.hypothesis,
confidence: parsed.confidence,
reasoning: parsed.reasoning,
specialization_match: parsed.specialization_match,
lineage: { input_id: cir.id, parent_kernel: this.parentKernelId }
};
}

buildProcessPrompt(cir, context) {
return `
Input Data:
Type: ${cir.type}
Normalized: ${JSON.stringify(cir.normalized, null, 2).substring(0, 1500)}

Your Memory (last 5 inputs):
${this.memory.history.slice(-5).map(h => `- ${h.hypothesis?.substring(0, 100)} (conf: ${h.confidence})`).join('\n')}

Your specialization: ${this.specialization}
Your seed: ${this.initializationSeed.toFixed(4)}

Process this input according to your specialization. Generate a hypothesis.`;
}

parseResponse(response) {
try {
const jsonMatch = response.match(/\{[\s\S]*\}/);
if (jsonMatch) {
return JSON.parse(jsonMatch[0]);
}
} catch(e) {}
return {
hypothesis: "Parse failed",
confidence: 0,
reasoning: "Failed to parse LLM response",
specialization_match: 0.5
};
}

// Called to update specialization based on feedback
updateSpecialization(feedback) {
// feedback: { input_id, was_useful, meta_score }
if (feedback.was_useful) {
this.memory.specializationScore =
(this.memory.specializationScore * 0.9) + (feedback.meta_score * 0.1);
} else {
this.memory.specializationScore *= 0.95;
}
}
}

module.exports = { BaseMiniLearner };
```

3.3 Mini-Forest (src/mini-forests/mini-forest.js)

```javascript
const { BaseMiniLearner } = require('./base-mini-learner');
const aggregationMethods = require('./aggregation');

class MiniForest {
constructor(config) {
this.id = config.id || crypto.randomUUID();
this.parentKernelId = config.parentKernelId;
this.name = config.name || `forest_${this.id.substring(0, 8)}`;
this.learners = [];
this.aggregationMethod = config.aggregationMethod || 'weighted_average';
this.nLearners = config.nLearners || 4;
}

async spawnLearners(count, baseConfig) {
const learners = [];
for (let i = 0; i < (count || this.nLearners); i++) {
const specialization = this.getSpecializationForIndex(i);
const learner = new BaseMiniLearner({
id: `${this.id}_learner_${i}`,
parentKernelId: this.parentKernelId,
name: `${this.name}_L${i}`,
model: baseConfig.model || 'llama3.2:3b',
initializationSeed: baseConfig.seedOffset + i,
specialization: specialization
});
learners.push(learner);
}
this.learners = learners;
return learners;
}

getSpecializationForIndex(idx) {
const specializations = [
'syntax', 'semantics', 'structure', 'patterns',
'anomalies', 'transformations', 'embeddings', 'relationships'
];
return specializations[idx % specializations.length];
}

async process(cir, context = {}) {
// Run all learners in parallel
const learnerPromises = this.learners.map(learner => learner.process(cir, context));
const learnerResults = await Promise.all(learnerPromises);

// Aggregate hypotheses
const aggregated = this.aggregate(learnerResults);

return {
forest_id: this.id,
aggregation_method: this.aggregationMethod,
learner_results: learnerResults,
aggregated_hypothesis: aggregated.hypothesis,
aggregated_confidence: aggregated.confidence,
internal_agreement: aggregated.agreement_score,
diversity_score: this.computeDiversity(learnerResults)
};
}

aggregate(learnerResults) {
const method = aggregationMethods[this.aggregationMethod] || aggregationMethods.weighted_average;
return method(learnerResults);
}

computeDiversity(learnerResults) {
// Measure variance in hypotheses
const confidences = learnerResults.map(r => r.confidence);
const meanConf = confidences.reduce((a,b) => a+b, 0) / confidences.length;
const variance = confidences.reduce((a,b) => a + Math.pow(b - meanConf, 2), 0) / confidences.length;
return Math.min(1, variance * 4); // Normalize
}

async addLearner(config) {
const learner = new BaseMiniLearner({
...config,
id: `${this.id}_learner_${this.learners.length}`,
parentKernelId: this.parentKernelId
});
this.learners.push(learner);
return learner;
}

removeLearner(learnerId) {
this.learners = this.learners.filter(l => l.id !== learnerId);
}
}

module.exports = { MiniForest };
```

3.4 Base Kernel (src/kernels/base-kernel.js)

```javascript
const { MiniForest } = require('../mini-forests/mini-forest');

class BaseKernel {
constructor(config) {
this.id = config.id || crypto.randomUUID();
this.parentLaneId = config.parentLaneId;
this.name = config.name || `kernel_${this.id.substring(0, 8)}`;
this.category = config.category; // text, numeric, symbolic, world, experimental
this.miniForests = [];
this.relevanceThreshold = config.relevanceThreshold || 0.3;
this.activeState = 'learn'; // learn, ignore, rest
this.lastRestStart = null;
this.stats = {
accepted: 0,
ignored: 0,
rested: 0,
processed: 0
};
}

async spawnMiniForest(config) {
const forest = new MiniForest({
id: `${this.id}_forest_${this.miniForests.length}`,
parentKernelId: this.id,
name: config.name || `forest_${this.miniForests.length}`,
aggregationMethod: config.aggregationMethod || 'weighted_average',
nLearners: config.nLearners || 4
});
await forest.spawnLearners(config.nLearners, {
model: config.model || 'llama3.2:3b',
seedOffset: config.seedOffset || Math.random() * 1000
});
this.miniForests.push(forest);
return forest;
}

async evaluateAndProcess(cir) {
this.stats.processed++;

// First: evaluate relevance
const relevance = await this.evaluateRelevance(cir);

if (relevance.score < this.relevanceThreshold) {
this.stats.ignored++;
return {
kernel_id: this.id,
action: 'ignore',
relevance_score: relevance.score,
reasoning: relevance.reasoning
};
}

if (this.activeState === 'rest') {
this.stats.rested++;
return {
kernel_id: this.id,
action: 'rest',
relevance_score: relevance.score,
reasoning: 'Kernel in rest state'
};
}

// Process through all mini-forests
const forestPromises = this.miniForests.map(forest => forest.process(cir, { kernel: this }));
const forestResults = await Promise.all(forestPromises);

// Aggregate across forests (category forest level)
const aggregated = this.aggregateAcrossForests(forestResults);

this.stats.accepted++;

return {
kernel_id: this.id,
kernel_name: this.name,
action: 'accept',
relevance_score: relevance.score,
forest_results: forestResults,
aggregated_hypothesis: aggregated.hypothesis,
aggregated_confidence: aggregated.confidence,
category_agreement: aggregated.agreement_score,
reasoning: relevance.reasoning
};
}

async evaluateRelevance(cir) {
// Default implementation - can be overridden
// In production, this would call Ollama with a relevance prompt
return {
score: 0.5,
reasoning: 'Default relevance (override in subclass)'
};
}

aggregateAcrossForests(forestResults) {
const hypotheses = forestResults.map(f => f.aggregated_hypothesis);
const confidences = forestResults.map(f => f.aggregated_confidence);
const avgConfidence = confidences.reduce((a,b) => a+b, 0) / confidences.length;

// Simple weighted average of hypotheses (in practice, more sophisticated)
return {
hypothesis: hypotheses.join(' | '),
confidence: avgConfidence,
agreement_score: Math.min(1, confidences.length > 1 ?
1 - (Math.max(...confidences) - Math.min(...confidences)) : 1)
};
}

rest(seconds = 10) {
this.activeState = 'rest';
this.lastRestStart = Date.now();
setTimeout(() => {
if (this.activeState === 'rest') {
this.activeState = 'learn';
this.lastRestStart = null;
}
}, seconds * 1000);
}

tick() {
if (this.activeState === 'rest' && this.lastRestStart) {
if (Date.now() - this.lastRestStart > 10000) {
this.activeState = 'learn';
this.lastRestStart = null;
}
}
}

getStats() {
return {
...this.stats,
forest_count: this.miniForests.length,
total_learners: this.miniForests.reduce((sum, f) => sum + f.learners.length, 0),
active_state: this.activeState
};
}
}

module.exports = { BaseKernel };
```

