3.6 Kernel Manager (Dynamic Injection) (src/kernels/kernel-manager.js)

```javascript
class KernelManager {
constructor() {
this.kernels = new Map(); // kernel_id -> kernel instance
this.kernelRegistry = new Map(); // kernel_type -> constructor
this.registerBuiltinKernels();
}

registerBuiltinKernels() {
// Dynamically load all kernel types
const kernelTypes = [
'tokenizer-kernel', 'embedding-kernel', 'matrix-kernel',
'clustering-kernel', 'rule-kernel', 'pattern-kernel',
'sequence-kernel', 'state-kernel', 'freeform-kernel', 'adapter-kernel'
];

kernelTypes.forEach(type => {
try {
const KernelClass = require(`./registry/${type}`);
this.kernelRegistry.set(type.replace('-kernel', ''), KernelClass);
} catch(e) {
console.warn(`Failed to load kernel type: ${type}`);
}
});
}

async addKernel(config) {
const { kernelType, parentLaneId, name, settings } = config;
const KernelClass = this.kernelRegistry.get(kernelType);

if (!KernelClass) {
throw new Error(`Unknown kernel type: ${kernelType}`);
}

const kernel = new KernelClass({
id: `kernel_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
parentLaneId,
name,
...settings
});

// Spawn default mini-forests if configured
if (settings.miniForests && settings.miniForests.length) {
for (const forestConfig of settings.miniForests) {
await kernel.spawnMiniForest(forestConfig);
}
} else {
// Default: spawn one mini-forest with 4 learners
await kernel.spawnMiniForest({ nLearners: 4, name: 'default_forest' });
}

this.kernels.set(kernel.id, kernel);
console.log(`[KernelManager] Added kernel: ${kernel.id} (${kernelType}) to lane ${parentLaneId}`);
return kernel;
}

async removeKernel(kernelId) {
if (this.kernels.has(kernelId)) {
this.kernels.delete(kernelId);
console.log(`[KernelManager] Removed kernel: ${kernelId}`);
return true;
}
return false;
}

getKernel(kernelId) {
return this.kernels.get(kernelId);
}

getKernelsByLane(laneId) {
return Array.from(this.kernels.values()).filter(k => k.parentLaneId === laneId);
}

async broadcastToKernels(cir, laneFilter = null) {
let targets = Array.from(this.kernels.values());
if (laneFilter) {
targets = targets.filter(k => k.parentLaneId === laneFilter);
}

const promises = targets.map(kernel => kernel.evaluateAndProcess(cir));
const results = await Promise.all(promises);
return results;
}

tick() {
for (const kernel of this.kernels.values()) {
kernel.tick();
}
}

getAllStats() {
return Array.from(this.kernels.entries()).map(([id, kernel]) => ({
id,
name: kernel.name,
stats: kernel.getStats()
}));
}
}

module.exports = { KernelManager };
```

3.7 Lane Manager (Dynamic Lane Management) (src/lanes/lane-manager.js)

```javascript
const { KernelManager } = require('../kernels/kernel-manager');

class LaneManager {
constructor() {
this.lanes = new Map(); // lane_id -> lane config
this.kernelManager = new KernelManager();
this.laneCategories = ['text', 'numeric', 'symbolic', 'world', 'experimental'];
}

async addLane(config) {
const laneId = config.id || `lane_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
const laneConfig = {
id: laneId,
name: config.name || `Lane_${laneId.substring(0, 8)}`,
category: config.category || 'experimental',
description: config.description || '',
kernels: [],
active: true,
createdAt: Date.now()
};

this.lanes.set(laneId, laneConfig);
console.log(`[LaneManager] Added lane: ${laneId} (${laneConfig.category})`);

// Spawn default kernels if specified
if (config.defaultKernels && config.defaultKernels.length) {
for (const kernelConfig of config.defaultKernels) {
await this.addKernelToLane(laneId, kernelConfig);
}
}

return laneConfig;
}

async removeLane(laneId) {
if (this.lanes.has(laneId)) {
// Remove all kernels in this lane
const kernels = this.kernelManager.getKernelsByLane(laneId);
for (const kernel of kernels) {
await this.kernelManager.removeKernel(kernel.id);
}
this.lanes.delete(laneId);
console.log(`[LaneManager] Removed lane: ${laneId}`);
return true;
}
return false;
}

async addKernelToLane(laneId, kernelConfig) {
const lane = this.lanes.get(laneId);
if (!lane) throw new Error(`Lane not found: ${laneId}`);

const kernel = await this.kernelManager.addKernel({
...kernelConfig,
parentLaneId: laneId
});

lane.kernels.push(kernel.id);
return kernel;
}

async removeKernelFromLane(laneId, kernelId) {
const lane = this.lanes.get(laneId);
if (!lane) throw new Error(`Lane not found: ${laneId}`);

await this.kernelManager.removeKernel(kernelId);
lane.kernels = lane.kernels.filter(kid => kid !== kernelId);
return true;
}

async broadcast(cir) {
const laneResults = [];

for (const [laneId, lane] of this.lanes.entries()) {
if (!lane.active) continue;

const kernelResults = await this.kernelManager.broadcastToKernels(cir, laneId);

// Lane-level aggregation (category forest)
const laneAggregation = this.aggregateLaneOutputs(kernelResults);

laneResults.push({
lane_id: laneId,
lane_name: lane.name,
category: lane.category,
kernel_results: kernelResults,
lane_aggregation: laneAggregation
});
}

return laneResults;
}

aggregateLaneOutputs(kernelResults) {
const acceptedResults = kernelResults.filter(r => r.action === 'accept');
if (acceptedResults.length === 0) {
return { has_output: false, agreement_score: 0 };
}

const confidences = acceptedResults.map(r => r.aggregated_confidence || r.relevance_score);
const avgConfidence = confidences.reduce((a,b) => a+b, 0) / confidences.length;
const maxConfidence = Math.max(...confidences);
const minConfidence = Math.min(...confidences);

return {
has_output: true,
kernel_count: acceptedResults.length,
avg_confidence: avgConfidence,
max_confidence: maxConfidence,
agreement_score: 1 - (maxConfidence - minConfidence),
total_learners: acceptedResults.reduce(
(sum, r) => sum + (r.forest_results?.length || 0), 0
)
};
}

getFullStats() {
const lanes = Array.from(this.lanes.entries()).map(([id, lane]) => ({
id,
name: lane.name,
category: lane.category,
kernel_count: lane.kernels.length,
active: lane.active
}));

return {
lanes,
kernels: this.kernelManager.getAllStats(),
total_lanes: this.lanes.size,
total_kernels: this.kernelManager.getAllStats().length,
total_learners: this.kernelManager.getAllStats().reduce(
(sum, k) => sum + (k.stats?.total_learners || 0), 0
)
};
}

tick() {
this.kernelManager.tick();
}
}

module.exports = { LaneManager };
```

3.8 Meta Analyzer (No Training) (src/meta/meta-analyzer.js)

```javascript
const fs = require('fs').promises;
const path = require('path');
const ollamaClient = require('../ollama/client');

class MetaAnalyzer {
constructor(config) {
this.model = config.model || 'llama3.3:70b';
this.curationOutputDir = config.outputDir || './data/curated';
this.systemPrompt = `You are a Meta Analyzer. You DO NOT train or update yourself.

Your role:
1. Observe all lane outputs for each input event
2. Compare agreement patterns across lanes, kernels, and learners
3. Score each output based on:
- confidence
- agreement with others
- diversity of perspective
- internal consistency
4. Identify high-signal data for downstream model training
5. Output curated dataset entries

You never update your own weights. You only curate.`;
}

async analyze(laneResults, inputCIR) {
const prompt = this.buildAnalysisPrompt(laneResults, inputCIR);

const response = await ollamaClient.chat(this.model, this.systemPrompt, prompt);
const parsed = this.parseAnalysis(response);

// Save curated dataset (does not train meta model)
await this.saveCuratedDataset(parsed, laneResults, inputCIR);

return parsed;
}

buildAnalysisPrompt(laneResults, inputCIR) {
// Build a compact representation of all outputs
const summary = this.summarizeLaneResults(laneResults);

return `
Input Event:
ID: ${inputCIR.id}
Type: ${inputCIR.type}
Data Preview: ${JSON.stringify(inputCIR.normalized, null, 2).substring(0, 500)}

Lane Outputs Summary:
${summary}

Analysis Tasks:
1. Score each lane's output (0-10) considering confidence, agreement, diversity
2. Identify which outputs are most valuable for training a downstream model
3. Detect disagreement clusters (these are valuable for exploration)
4. Output curated training examples for each high-value interpretation

Output JSON:
{
"lane_scores": [{"lane_id": "...", "score": 8, "reason": "..."}],
"top_interpretations": [{"lane_id": "...", "kernel_id": "...", "hypothesis": "...", "quality_score": 0.95}],
"disagreement_clusters": [{"topic": "...", "lanes": ["..."], "signal_strength": 0.8}],
"curated_examples": [
{
"input": {...},
"output": "...",
"source_lane": "...",
"source_kernel": "...",
"meta_confidence": 0.9,
"diversity_weight": 0.7
}
]
}`;
}

summarizeLaneResults(laneResults) {
let summary = '';
for (const lane of laneResults) {
summary += `\n--- Lane: ${lane.lane_name} (${lane.category}) ---\n`;
summary += `Agreement: ${lane.lane_aggregation.agreement_score}\n`;
summary += `Kernels: ${lane.kernel_results.length}\n`;

for (const kernel of lane.kernel_results.slice(0, 2)) { // Limit for prompt size
if (kernel.action === 'accept') {
summary += ` Kernel ${kernel.kernel_name}: ${kernel.aggregated_hypothesis?.substring(0, 200)}\n`;
summary += ` Confidence: ${kernel.aggregated_confidence}\n`;
}
}
}
return summary;
}

parseAnalysis(response) {
try {
const jsonMatch = response.match(/\{[\s\S]*\}/);
if (jsonMatch) {
return JSON.parse(jsonMatch[0]);
}
} catch(e) {
console.warn('[Meta] Failed to parse analysis:', e.message);
}
return {
lane_scores: [],
top_interpretations: [],
disagreement_clusters: [],
curated_examples: []
};
}

async saveCuratedDataset(parsed, laneResults, inputCIR) {
if (!parsed.curated_examples || parsed.curated_examples.length === 0) return;

await fs.mkdir(this.curationOutputDir, { recursive: true });
const curatedPath = path.join(this.curationOutputDir, 'dataset.jsonl');

for (const example of parsed.curated_examples) {
const enrichedExample = {
...example,
input: inputCIR.normalized,
input_id: inputCIR.id,
timestamp: Date.now(),
source_system_version: '32x_complexity_v1',
agreement_context: {
total_lanes: laneResults.length,
lane_agreement_scores: parsed.lane_scores
}
};
await fs.appendFile(curatedPath, JSON.stringify(enrichedExample) + '\n');
}

console.log(`[Meta] Saved ${parsed.curated_examples.length} curated examples to ${curatedPath}`);
}
}

module.exports = { MetaAnalyzer };
```

