if (client.readyState === WebSocket.OPEN) {
client.send(JSON.stringify({
type: 'ingest_result',
input_id: cir.id,
lane_results: laneResults,
meta_analysis: metaResult
}));
}
});

res.json({
input_id: cir.id,
lane_count: laneResults.length,
total_learners: laneManager.getFullStats().total_learners,
top_interpretations: metaResult.top_interpretations?.length || 0
});
});

app.post('/api/lanes/add', async (req, res) => {
const lane = await laneManager.addLane(req.body);
res.json(lane);
});

app.delete('/api/lanes/:laneId', async (req, res) => {
const success = await laneManager.removeLane(req.params.laneId);
res.json({ success });
});

app.post('/api/lanes/:laneId/kernels', async (req, res) => {
const kernel = await laneManager.addKernelToLane(req.params.laneId, req.body);
res.json({ kernel_id: kernel.id });
});

app.delete('/api/lanes/:laneId/kernels/:kernelId', async (req, res) => {
const success = await laneManager.removeKernelFromLane(req.params.laneId, req.params.kernelId);
res.json({ success });
});

app.get('/api/stats', (req, res) => {
res.json(laneManager.getFullStats());
});

// WebSocket connection
wss.on('connection', (ws) => {
console.log('[WebSocket] Client connected');

ws.on('message', async (message) => {
try {
const data = JSON.parse(message);
if (data.type === 'ingest') {
const cir = new CIR(data.data, data.dataType, data.metadata);
const laneResults = await laneManager.broadcast(cir);
const metaResult = await metaAnalyzer.analyze(laneResults, cir);
ws.send(JSON.stringify({
type: 'result',
input_id: cir.id,
lane_results: laneResults,
meta_analysis: metaResult
}));
} else if (data.type === 'get_stats') {
ws.send(JSON.stringify({
type: 'stats',
stats: laneManager.getFullStats()
}));
}
} catch(e) {
ws.send(JSON.stringify({ type: 'error', message: e.message }));
}
});
});

// Periodic tick
setInterval(() => laneManager.tick(), 5000);

// Headless mode
if (process.env.HEADLESS === 'true') {
console.log('Running in headless mode...');
const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
console.log('Headless mode. Enter JSON lines or "exit"');

rl.on('line', async (line) => {
if (line === 'exit') process.exit();
try {
const data = JSON.parse(line);
const cir = new CIR(data.data, data.type || 'text', data.metadata);
const laneResults = await laneManager.broadcast(cir);
const metaResult = await metaAnalyzer.analyze(laneResults, cir);
console.log(JSON.stringify({
input_id: cir.id,
total_learners: laneManager.getFullStats().total_learners,
top_interpretations: metaResult.top_interpretations?.slice(0, 3)
}, null, 2));
} catch(e) {
console.error('Error:', e.message);
}
});
} else {
// Normal server mode
const PORT = process.env.PORT || 3000;

loadDefaultConfig().then(() => {
server.listen(PORT, () => {
console.log(`
