const { BaseKernel } = require('../base-kernel');
const ollamaClient = require('../../ollama/client');

class MatrixKernel extends BaseKernel {
constructor(config) {
super({
...config,
category: 'numeric',
name: config.name || 'MatrixLearner'
});
this.relevancePrompt = this.buildRelevancePrompt();
}

buildRelevancePrompt() {
return `You are a matrix/numerical kernel. Determine if incoming data has matrix structure.
Output JSON: { "score": 0-1, "reasoning": "..." }`;
}

async evaluateRelevance(cir) {
if (cir.type !== 'numeric' && cir.type !== 'json') {
return { score: 0, reasoning: 'Not numeric data' };
}

const prompt = `
Data: ${JSON.stringify(cir.normalized, null, 2).substring(0, 500)}
Is this matrix-shaped data? (2D array, numerical grid, tensor-like)
${this.relevancePrompt}`;

const response = await ollamaClient.chat('llama3.2:3b', this.relevancePrompt, prompt);
try {
const jsonMatch = response.match(/\{[\s\S]*\}/);
if (jsonMatch) {
const parsed = JSON.parse(jsonMatch[0]);
return { score: parsed.score, reasoning: parsed.reasoning };
}
} catch(e) {}

// Heuristic fallback
const hasMatrixShape = cir.normalized.is_matrix === true ||
(cir.normalized.values && cir.normalized.length > 4);
return { score: hasMatrixShape ? 0.7 : 0.2, reasoning: 'Heuristic evaluation' };
}
}

module.exports = { MatrixKernel };
