const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const { LaneManager } = require('./lanes/lane-manager');
const { MetaAnalyzer } = require('./meta/meta-analyzer');
const { CIR } = require('./core/cir');
const path = require('path');
const fs = require('fs');

const app = express();
