const wss = new WebSocket.Server({ server });

const laneManager = new LaneManager();
const metaAnalyzer = new MetaAnalyzer({ model: 'llama3.3:70b' });

// Load default configuration
async function loadDefaultConfig() {
const configPath = path.join(__dirname, '../configs/default-lanes.json');
if (fs.existsSync(configPath)) {
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
for (const laneConfig of config.lanes) {
await laneManager.addLane(laneConfig);
}
} else {
// Create default lanes
await laneManager.addLane({
name: 'Text Analysis',
category: 'text',
defaultKernels: [
{ kernelType: 'tokenizer', name: 'Tokenizer', settings: { miniForests: [{ nLearners: 4 }] } },
{ kernelType: 'embedding', name: 'Embedding', settings: { miniForests: [{ nLearners: 4 }] } }
]
});

await laneManager.addLane({
name: 'Numeric Analysis',
category: 'numeric',
defaultKernels: [
{ kernelType: 'matrix', name: 'MatrixLearner', settings: { miniForests: [{ nLearners: 4 }] } },
{ kernelType: 'clustering', name: 'Clustering', settings: { miniForests: [{ nLearners: 4 }] } }
]
});

await laneManager.addLane({
name: 'Symbolic Analysis',
category: 'symbolic',
defaultKernels: [
{ kernelType: 'rule', name: 'RuleLearner', settings: { miniForests: [{ nLearners: 4 }] } },
{ kernelType: 'pattern', name: 'PatternMatcher', settings: { miniForests: [{ nLearners: 4 }] } }
]
});
}
}

// Static files
app.use(express.static(path.join(__dirname, 'ui/public')));
app.use(express.json({ limit: '50mb' }));

// API endpoints
app.get('/api/status', (req, res) => {
res.json(laneManager.getFullStats());
});

app.post('/api/ingest', async (req, res) => {
const { data, type, metadata } = req.body;
const cir = new CIR(data, type || 'text', metadata);

const laneResults = await laneManager.broadcast(cir);
const metaResult = await metaAnalyzer.analyze(laneResults, cir);

// Broadcast via WebSocket
wss.clients.forEach(client => {
if (client.readyState === WebSocket.OPEN) {
client.send(JSON.stringify({
type: 'ingest_result',
input_id: cir.id,
lane_results: laneResults,
meta_analysis: metaResult
}));
}
});

res.json({
input_id: cir.id,
lane_count: laneResults.length,
total_learners: laneManager.getFullStats().total_learners,
top_interpretations: metaResult.top_interpretations?.length || 0
});
});

app.post('/api/lanes/add', async (req, res) => {
const lane = await laneManager.addLane(req.body);
res.json(lane);
});

app.delete('/api/lanes/:laneId', async (req, res) => {
const success = await laneManager.removeLane(req.params.laneId);
res.json({ success });
});

app.post('/api/lanes/:laneId/kernels', async (req, res) => {
const kernel = await laneManager.addKernelToLane(req.params.laneId, req.body);
res.json({ kernel_id: kernel.id });
});

app.delete('/api/lanes/:laneId/kernels/:kernelId', async (req, res) => {
const success = await laneManager.removeKernelFromLane(req.params.laneId, req.params.kernelId);
res.json({ success });
});

app.get('/api/stats', (req, res) => {
res.json(laneManager.getFullStats());
});

// WebSocket connection
wss.on('connection', (ws) => {
console.log('[WebSocket] Client connected');

ws.on('message', async (message) => {
try {
const data = JSON.parse(message);
if (data.type === 'ingest') {
const cir = new CIR(data.data, data.dataType, data.metadata);
const laneResults = await laneManager.broadcast(cir);
const metaResult = await metaAnalyzer.analyze(laneResults, cir);
ws.send(JSON.stringify({
type: 'result',
input_id: cir.id,
lane_results: laneResults,
meta_analysis: metaResult
}));
} else if (data.type === 'get_stats') {
ws.send(JSON.stringify({
type: 'stats',
stats: laneManager.getFullStats()
}));
}
} catch(e) {
ws.send(JSON.stringify({ type: 'error', message: e.message }));
}
});
});

// Periodic tick
setInterval(() => laneManager.tick(), 5000);

// Headless mode
if (process.env.HEADLESS === 'true') {
console.log('Running in headless mode...');
