# ─────────────────────────────────────────────────────────────────────────────
# Shared live state (mutated from async poll loop, read by UI timers)
# ─────────────────────────────────────────────────────────────────────────────
state: Dict = {
    \"inem\": {},
    \"kg\": {},
    \"mmo_vectors\": 0,
    \"mmo_growth\": [],       # [(ts, count), ...]
    \"buffer_episodes\": 0,
    \"ingest_rate\": 0.0,     # vectors/s
    \"ram_used_gb\": 0.0,
    \"ram_total_gb\": 0.0,
    \"ram_pct\": 0.0,
    \"vram_used_mb\": 0.0,
    \"vram_total_mb\": 0.0,
    \"cpu_pct\": 0.0,
    \"domain_rows\": [],      # list of domain stat dicts
    \"kg_health\": {},
    \"last_poll_ok\": False,
    \"feeder_lines\": [],     # ring buffer of feeder stdout lines
    \"terminal_lines\": [],   # general terminal
    \"processes\": {},        # name -> subprocess.Popen or None
}
_state_lock = threading.Lock()
_prev_mmo   = 0
_prev_ts    = time.monotonic()

# ─────────────────────────────────────────────────────────────────────────────
# Process manager  (backend, inem, feeder, stress runner, etc.)
# ─────────────────────────────────────────────────────────────────────────────
_procs: Dict[str, Optional[subprocess.Popen]] = {
    \"backend\": None,
    \"inem\":    None,
    \"feeder\":  None,
}

def _is_alive(name: str) -> bool:
    p = _procs.get(name)
    return p is not None and p.poll() is None

def _proc_status(name: str) -> str:
    return \"▶ running\" if _is_alive(name) else \"■ stopped\"

def _start_proc(name: str, cmd: List[str], log_key: str = \"terminal_lines\"):
    if _is_alive(name):
        _append_log(log_key, f\"[{name}] already running (PID {_procs[name].pid})\")
        return
    _append_log(log_key, f\"[{name}] starting: {' '.join(cmd)}\")
    p = subprocess.Popen(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    _procs[name] = p

    def _drain():
        for line in iter(p.stdout.readline, \"\"):
            _append_log(log_key, f\"[{name}] {line.rstrip()}\")
        p.stdout.close()

    threading.Thread(target=_drain, daemon=True).start()

def _stop_proc(name: str, log_key: str = \"terminal_lines\"):
    p = _procs.get(name)
    if p and p.poll() is None:
        p.terminate()
        try:
            p.wait(timeout=5)
        except subprocess.TimeoutExpired:
            p.kill()
        _append_log(log_key, f\"[{name}] stopped (was PID {p.pid})\")
    else:
        _append_log(log_key, f\"[{name}] not running\")
    _procs[name] = None

def _append_log(key: str, line: str, maxlines: int = 300):
    with _state_lock:
        buf = state[key]
        buf.append(line)
        while len(buf) > maxlines:
            buf.pop(0)

def _run_cmd(cmd_str: str):
    \"\"\"Run an arbitrary shell command and capture into terminal log.\"\"\"
    _append_log(\"terminal_lines\", f\"$ {cmd_str}\")
    p = subprocess.Popen(
        cmd_str,
        shell=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )

    def _drain():
        for line in iter(p.stdout.readline, \"\"):
            _append_log(\"terminal_lines\", line.rstrip())
        p.stdout.close()

    threading.Thread(target=_drain, daemon=True).start()

