async def _start_avi_server():
    try:
        from aiohttp import web as aweb

        async def _serve_avi(request):
            if AVI_HTML.exists():
                return aweb.Response(
                    body=AVI_HTML.read_bytes(),
                    content_type=\"text/html\",
                )
            return aweb.Response(text=\"AVI ui_design.html not found\", status=404)

        avi_app = aweb.Application()
        avi_app.router.add_get(\"/\", _serve_avi)
        avi_app.router.add_get(\"/avi\", _serve_avi)
        runner = aweb.AppRunner(avi_app)
        await runner.setup()
        site = aweb.TCPSite(runner, \"127.0.0.1\", AVI_PORT)
        await site.start()
        _append_log(\"terminal_lines\", f\"[avi] static server on http://localhost:{AVI_PORT}\")
    except Exception as e:
        _append_log(\"terminal_lines\", f\"[avi] server failed to start: {e}\")

# ─────────────────────────────────────────────────────────────────────────────
# Async polling loop (runs every 1.5 s)
# ─────────────────────────────────────────────────────────────────────────────
async def _poll_loop():
    global _prev_mmo, _prev_ts
    async with aiohttp.ClientSession() as session:
        while True:
            now = time.monotonic()
            # ── InEM stats ────────────────────────────────────────────────
            try:
                async with session.get(f\"{INEM_URL}/stats\", timeout=aiohttp.ClientTimeout(total=2)) as r:
                    data = await r.json()
                    new_mmo = data.get(\"mmo_vectors\", 0)
                    dt = now - _prev_ts
                    rate = max(0.0, (new_mmo - _prev_mmo) / dt) if dt > 0 else 0.0
                    _prev_mmo, _prev_ts = new_mmo, now
                    with _state_lock:
                        state[\"inem\"]            = data
                        state[\"mmo_vectors\"]     = new_mmo
                        state[\"buffer_episodes\"] = data.get(\"buffer_episodes\", 0)
                        state[\"domain_rows\"]     = data.get(\"domains\", [])
                        state[\"ingest_rate\"]     = round(rate, 1)
                        state[\"last_poll_ok\"]    = True
                        history = state[\"mmo_growth\"]
                        history.append((now, new_mmo))
                        if len(history) > 120:
                            history.pop(0)
            except Exception:
                with _state_lock:
                    state[\"last_poll_ok\"] = False

            # ── KidsGame health ───────────────────────────────────────────
            try:
                async with session.get(f\"{KIDSGAME_URL}/api/health\",
                                       timeout=aiohttp.ClientTimeout(total=2)) as r:
                    with _state_lock:
                        state[\"kg_health\"] = await r.json()
            except Exception:
                with _state_lock:
                    state[\"kg_health\"] = {}

            # ── RAM / CPU (psutil, synchronous — fast) ────────────────────
            vm = psutil.virtual_memory()
            with _state_lock:
                state[\"ram_used_gb\"]  = round(vm.used  / 1e9, 1)
                state[\"ram_total_gb\"] = round(vm.total / 1e9, 1)
                state[\"ram_pct\"]      = round(vm.percent, 1)
                state[\"cpu_pct\"]      = round(psutil.cpu_percent(interval=None), 1)

            # ── VRAM (nvidia-smi) — non-blocking ─────────────────────────
            try:
                out = subprocess.check_output(
                    [\"nvidia-smi\", \"--query-gpu=memory.used,memory.total\",
                     \"--format=csv,noheader,nounits\"],
                    timeout=2, stderr=subprocess.DEVNULL
                ).decode().strip().split(\",\")
                with _state_lock:
                    state[\"vram_used_mb\"]  = float(out[0])
                    state[\"vram_total_mb\"] = float(out[1])
            except Exception:
                pass

            await asyncio.sleep(1.5)

# ─────────────────────────────────────────────────────────────────────────────
# Helpers for the UI
# ─────────────────────────────────────────────────────────────────────────────
def _s(key):
